"""Core authentication and header parsing guard."""

from typing import Dict, Optional
from models import AuthUser


class AuthGuard:
    def __init__(self, valid_tokens: Dict[str, AuthUser]):
        self.valid_tokens = valid_tokens

    def authenticate(self, headers: Dict[str, str]) -> Optional[AuthUser]:
        # Check Primary Authorization header or Secondary X-API-Token header
        auth_header = headers.get("Authorization")
        api_token = headers.get("X-API-Token")

        token = None
        if auth_header:
            # BUG: Case-sensitive prefix check fails on lowercase "bearer <token>"
            if auth_header.startswith("Bearer "):
                token = auth_header[7:].strip()
            else:
                # BUG: If Authorization header exists with non-Bearer format, it returns None
                # and completely ignores valid X-API-Token fallback!
                return None
        elif api_token:
            token = api_token.strip()

        if not token or token not in self.valid_tokens:
            return None
        user = self.valid_tokens[token]
        return user if user.is_active else None

