"""HTTP request processing pipeline."""

from typing import Any, Dict, Optional
from auth_guard import AuthGuard
from distractor_audit import AuditLoggerMiddleware
from models import AuthUser


class RequestPipeline:
    def __init__(self, guard: AuthGuard):
        self.guard = guard
        self.audit = AuditLoggerMiddleware()

    def process(self, headers: Dict[str, str], payload: Any) -> Dict[str, Any]:
        self.audit.inspect_request(headers)
        user = self.guard.authenticate(headers)
        if not user:
            return {"status": 401, "error": "Unauthorized"}
        return {"status": 200, "user_id": user.user_id, "data": payload}

