from typing import Dict, Optional
from models import AuthUser


class AuthGuard:
    def __init__(self, valid_tokens: Dict[str, AuthUser]):
        self.valid_tokens = valid_tokens

    def authenticate(self, headers: Dict[str, str]) -> Optional[AuthUser]:
        auth_header = headers.get("Authorization")
        api_token = headers.get("X-API-Token")

        token = None
        if auth_header:
            parts = auth_header.split(maxsplit=1)
            if len(parts) == 2 and parts[0].lower() == "bearer":
                token = parts[1].strip()
            elif len(parts) == 1:
                token = parts[0].strip()

        # Fallback to secondary header if primary did not yield a valid matched token
        if (not token or token not in self.valid_tokens) and api_token:
            token = api_token.strip()

        if not token or token not in self.valid_tokens:
            return None
        user = self.valid_tokens[token]
        return user if user.is_active else None
